{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Raltitrexed, a structurally related antifolate with a benzoylglutamate moiety, exhibited very limited CSF penetration (0.6–2.0%) in nonhuman primates, directly demonstrating that antifolate drugs of this class do not achieve meaningful CNS access despite active folate transporter recognition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A polar glutamate-containing radiotracer showed brain uptake of only 0.34 %ID/g in mice, consistent with negligible BBB penetration for highly ionized glutamic-acid-bearing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Another glutamate-containing radiotracer showed brain uptake of only 0.47 %ID/g in mice, further supporting poor brain penetration for this class of highly polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A 5-methyltetrahydrofolate analogue equilibrated with CSF within 3 h after IV bolus in dogs, showing that folate-like structures can access the CNS via active transport.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "N5-methyl tetrahydrofolate was recovered in dog CSF after IV administration against a concentration gradient, indicating a specific transporter-mediated uptake into the CNS.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is pemetrexed, a highly polar, fully ionized antifolate with a terminal glutamate. Although natural folates can cross the BBB via active transport, the closest antifolate comparator (raltitrexed) shows very poor CSF penetration, and other polar glutamate-containing radiotracers show negligible brain uptake. The very low passive permeability prior and likely efflux liability outweigh the supportive folate-transport evidence, so meaningful CNS access after systemic administration is unlikely.",
  "evidence_gaps": [
    "No direct CSF or brain penetration measurement for pemetrexed itself in the provided evidence.",
    "The extent to which pemetrexed is transported by FRα/RFC at the BBB versus effluxed by BCRP/MRP4 is not directly assessed.",
    "Human CNS exposure data for the query are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

